import GetServerSideProps">GetServerSideProps</data-lsp> } </span><span>from</span><span> </span><span>"next"</span><span>;</span></p><p><span>export</span><span> </span><span>const</span><span> </span><span><data-lsp lsp="const getServerSideProps: (context: GetServerSidePropsContext<ParsedUrlQuery, PreviewData>) => Promise<{
    props: {
